@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@300;400;500;600;700&family=DM+Mono:wght@400;500&display=swap');

* { margin: 0; padding: 0; box-sizing: border-box; }

:root {
  --navy: #0f1f3d;
  --blue: #1a3a6b;
  --accent: #2563eb;
  --accent-light: #dbeafe;
  --teal: #0ea5b0;
  --gold: #c9972a;
  --text: #1e293b;
  --muted: #64748b;
  --border: #e2e8f0;
  --bg: #f8fafc;
  --white: #ffffff;
}

body {
  font-family: 'DM Sans', sans-serif;
  color: var(--text);
  background: var(--white);
  font-size: 10px;
  line-height: 1.5;
  -webkit-print-color-adjust: exact;
  print-color-adjust: exact;
}

.invoice-wrapper {
  width: 210mm;
  min-height: 297mm;
  height: 297mm;
  margin: 0 auto;
  background: var(--white);
  display: flex;
  flex-direction: column;
  position: relative;
  overflow: hidden;
}

.header {
  padding: 18px 24px 14px;
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  position: relative;
  overflow: hidden;
}

.logo-area img {
  height: 44px;
  filter: brightness(0) invert(1);
}
.logo-area .company-name {
  color: var(--white);
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 0.04em;
  margin-top: 4px;
}
.logo-area .company-sub {
  color: rgba(255,255,255,0.55);
  font-size: 8px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  margin-top: 1px;
}

.header-right {
  text-align: right;
  position: relative; z-index: 1;
}
.invoice-title {
  color: #000;
  font-size: 10px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  margin-bottom: 4px;
}
.invoice-number {
  color: #000;
  font-family: 'DM Mono', monospace;
  font-size: 17px;
  font-weight: 500;
  letter-spacing: 0.02em;
}
.ncf-badge {
  color: #000;
  font-family: 'DM Mono', monospace;
  font-size: 9px;
  margin-top: 4px;
  letter-spacing: 0.06em;
}
.rnc-line {
  color: #000;
  font-size: 7.5px;
  margin-top: 3px;
  letter-spacing: 0.05em;
  text-transform: uppercase;
}

.stripe {
  height: 4px;
  background: linear-gradient(90deg, var(--accent) 0%, var(--teal) 50%, var(--gold) 100%);
}

.meta-row {
  display: flex;
  gap: 0;
  border-bottom: 1px solid var(--border);
}
.meta-cell {
  flex: 1;
  padding: 10px 14px;
  border-right: 1px solid var(--border);
}
.meta-cell:last-child { border-right: none; }
.meta-label {
  font-size: 7px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--muted);
  margin-bottom: 2px;
}
.meta-value {
  font-size: 10px;
  font-weight: 600;
  color: var(--text);
}
.meta-value.accent { color: var(--accent); }
.meta-value.mono { font-family: 'DM Mono', monospace; font-size: 9px; }

.parties {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0;
  border-bottom: 1px solid var(--border);
}
.party-block {
  padding: 12px 16px;
  border-right: 1px solid var(--border);
}
.party-block:last-child { border-right: none; }
.party-heading {
  font-size: 7px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--accent);
  border-bottom: 1.5px solid var(--accent-light);
  padding-bottom: 4px;
  margin-bottom: 8px;
}
.party-name {
  font-size: 11px;
  font-weight: 700;
  color: var(--navy);
  margin-bottom: 3px;
}
.party-detail {
  font-size: 8.5px;
  color: var(--muted);
  margin-bottom: 1px;
}
.party-detail span {
  font-weight: 600;
  color: var(--text);
}

.insurance-row {
  background: linear-gradient(135deg, #eff6ff 0%, #f0fdff 100%);
  border-bottom: 1px solid var(--border);
  padding: 8px 16px;
  display: flex;
  align-items: center;
  gap: 24px;
}
.ins-chip {
  display: flex;
  align-items: center;
  gap: 6px;
}
.ins-chip-label {
  font-size: 7px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--accent);
}
.ins-chip-value {
  font-size: 9.5px;
  font-weight: 700;
  color: var(--navy);
}
.ins-dot { width: 4px; height: 4px; border-radius: 50%; background: var(--border); }

.items-section { padding: 0 16px; margin-top: 14px; }
.section-title {
  font-size: 7px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--muted);
  margin-bottom: 6px;
}

table.items {
  width: 100%;
  border-collapse: collapse;
}
table.items thead tr {
  background: var(--navy);
}
table.items thead th {
  color: var(--white);
  font-size: 7.5px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  padding: 7px 10px;
  text-align: left;
}
table.items thead th:last-child { text-align: right; }
table.items tbody tr {
  border-bottom: 1px solid var(--border);
}
table.items tbody tr:nth-child(even) { background: var(--bg); }
table.items tbody td {
  padding: 8px 10px;
  font-size: 9px;
  color: var(--text);
  vertical-align: top;
}
table.items tbody td:last-child { text-align: right; font-family: 'DM Mono', monospace; }
.item-name { font-weight: 600; color: var(--navy); }
.item-group { font-size: 7.5px; color: var(--muted); margin-top: 1px; }

.cov-pill {
  display: inline-block;
  padding: 1px 6px;
  border-radius: 10px;
  font-size: 9px;
  font-weight: 600;
}

.totals-area {
  display: flex;
  justify-content: flex-end;
  padding: 14px 16px 0;
}
.totals-box {
  width: 220px;
  border: 1px solid var(--border);
  border-radius: 6px;
  overflow: hidden;
}
.print-format th{
    background: #fff !important;
    color: #000 !important;
}
.totals-row {
  display: flex;
  justify-content: space-between;
  padding: 5px 12px;
  font-size: 9px;
  border-bottom: 1px solid var(--border);
}
.totals-row:last-child { border-bottom: none; }
.totals-row.grand {
  background: #fff;
  color: var(--white);
  padding: 8px 12px;
}
.totals-row.grand .t-label { font-weight: 700; font-size: 9.5px; }
.totals-row.grand .t-val {
  font-family: 'DM Mono', monospace;
  font-size: 12px;
  font-weight: 700;
}
.t-label { color: var(--muted); }
.t-val { font-family: 'DM Mono', monospace; font-weight: 600; color: var(--text); }
.t-val.blue { color: var(--accent); }

.payments-area {
  padding: 10px 16px 0;
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
}
.pay-card {
  flex: 1;
  min-width: 100px;
  border: 1px solid var(--border);
  border-radius: 6px;
  padding: 8px 12px;
  background: var(--bg);
}
.pay-card.ars { border-left: 3px solid var(--accent); }
.pay-card.cash { border-left: 3px solid var(--teal); }
.pay-mode { font-size: 7px; font-weight: 700; text-transform: uppercase; letter-spacing: 0.1em; color: var(--muted); }
.pay-amount { font-family: 'DM Mono', monospace; font-size: 14px; font-weight: 700; color: var(--navy); margin-top: 2px; }

.in-words {
  margin: 10px 16px 0;
  padding: 6px 12px;
  background: var(--bg);
  border-left: 3px solid var(--gold);
  font-size: 8.5px;
  color: var(--muted);
  font-style: italic;
}
.in-words strong { color: var(--text); font-style: normal; }

.footer-section {
  margin: 14px 16px 0;
  display: flex;
  justify-content: center;
  gap: 14px;
  align-items: flex-start;
}
.qr-box {
  padding: 20px;
  text-align: center;
  background: var(--white);
  min-width: 130px;
}
.qr-box img { width: 100px; height: 100px; }
.qr-label { font-size: 7px; color: var(--muted); margin-top: 4px; font-weight: 600; letter-spacing: 0.08em; }

.ecf-info {
  flex: 1;
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 10px 14px;
  background: var(--bg);
}
.ecf-title {
  font-size: 8px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--accent);
  margin-bottom: 8px;
  border-bottom: 1px solid var(--border);
  padding-bottom: 4px;
}
.ecf-row {
  display: flex;
  justify-content: space-between;
  margin-bottom: 4px;
  align-items: center;
}
.ecf-row-label { font-size: 7.5px; color: var(--muted); font-weight: 600; }
.ecf-row-val { font-family: 'DM Mono', monospace; font-size: 8.5px; font-weight: 600; color: var(--text); }
.ecf-row-val.green { color: #16a34a; }
.ecf-row-val.red { color: #dc2626; }

.status-badge {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 2px 8px;
  border-radius: 20px;
  font-size: 7.5px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.06em;
}
.status-accepted { background: #dcfce7; color: #15803d; }
.status-dot { width: 5px; height: 5px; border-radius: 50%; background: currentColor; }

.page-footer {
  margin-top: auto;
  border-top: 1px solid var(--border);
  padding: 10px 16px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  background: var(--bg);
}
.footer-addr {
  font-size: 7.5px;
  color: var(--muted);
  line-height: 1.6;
}
.footer-addr strong { color: var(--text); }
.footer-legal {
  font-size: 7px;
  color: var(--muted);
  text-align: right;
  line-height: 1.6;
}

@media print {
  body { margin: 0; }
  .invoice-wrapper { width: 100%; min-height: 100vh; }

  @media print {
  @page {
    size: A4;
    margin: 0;
  }
  body { margin: 0; }
  .invoice-wrapper {
    width: 100%;
    height: 100vh;
    overflow: hidden;
  }
}
